import {coordinateName,automaticPlaceChanges,lookupBrowserArea} from './location.js';
import {h as html,t as tr,setLanguage,getLanguage,locale} from './i18n.js';
import {preparePhotos} from './photos.js';
import {APP_VERSION,RELEASES_URL,checkUpdate} from './updates.js';
import QRCode from 'qrcode';
import {strFromU8} from 'fflate';
import {Store} from './store.js';
import {uid,now,record,revise,put,get,active,merge,resolve,migrateLegacy,timezoneValid,localTime as formatTime,ev100,shutterSeconds,comparable,suggest,validateRecords} from './model.js';
import {planTripExport,exportTripPart,decodeField,unpack,sha256,escapeHTML as e,MAX_PACKAGE} from './packets.js';
import {native,nativePlaceNames,lookupNativePlace,nativeCamera,captureReference,pendingCaptures,acknowledgeCapture,shareStagedCapture,readCaptureFile,installUpdate,getLightCapability,measureLight,stopMeter,locate,deliver} from './native.js';
import {daylight} from './sun.js';
