const localTime=(value,zone,seconds=false)=>formatTime(value,zone,seconds,locale());
const $=s=>document.querySelector(s), app=$('#app'),modal=$('#modal');
const store=new Store();let formSave=Promise.resolve(),updateReady=false,editVersion=0,formDirty=false,pendingExports=[],exportSnapshot=null;let snapshot,state,local,view='field',selected=null,urls=new Map(),pendingImport=null,sample=null,saving=0,search='',toastTimer;
let availableUpdate=null;
let lightCapability={available:false,mode:'checking',title:tr('Checking built-in light meter…'),detail:''};
const androidDownload='https://github.com/Devilzhu1985/hk-scout/releases/download/v2.1.0-preview.1/scout-2.1.0-preview.1-debug.apk';
const gpsPending=new Set(),gpsErrors=new Map(),dirtyFields=new Set(),savedVersions=new Map();
const roles=['unclassified','identification','environment','material','lighting','gray reference','bracket','panorama','detail','signage'];
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(2)).toLocaleString(locale()):'—';
const button=(label,action,id='',cls='')=>html`<button class="${cls}" data-action="${action}" data-id="${e(id)}">${tr(label)}</button>`;
const trip=()=>get(state,local.activeTrip);
const sets=()=>active(state,'set').filter(s=>s.tripId===local.activeTrip);
const fieldsets=()=>sets().sort((a,b)=>b.startedAt.localeCompare(a.startedAt));
const fieldAssets=()=>active(state,'asset').filter(a=>a.tripId===local.activeTrip);
const notice=(text,error=false)=>{clearTimeout(toastTimer);$('#notice').textContent=tr(text);$('#notice').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#notice').className='',error?10000:4500);};
function labelFields(root){for(const label of root.querySelectorAll('label:not([for])')){const input=label.nextElementSibling;if(input?.matches('input,select,textarea')){input.id ||= 'field-'+uid();label.htmlFor=input.id;}}}
function show(html){modal.innerHTML=html;labelFields(modal);modal.showModal();}
function close(){modal.close();stopMeter();}
async function refresh(){snapshot=await store.read();state=snapshot.state;local=snapshot.local;setLanguage(local.language||(/^zh/i.test(navigator.language)?'zh':'en'));const previews=new Set(state.records.filter(r=>r.kind==='asset').map(r=>r.blobId));for(const b of snapshot.blobs)if(previews.has(b.id)&&!urls.has(b.id))urls.set(b.id,URL.createObjectURL(b.blob));}
function savedLabel(){const el=$('#saved');if(el)el.textContent=saving?tr('Saving…'):formDirty?tr('Unsaved edit · leave field to save'):tr('Saved on this device');}
async function change(fn,redraw=true){saving++;savedLabel();try{await store.change(fn);await refresh();if(redraw)render();}catch(err){notice(tr('Not saved: ')+tr(err.message),true);throw err;}finally{saving--;savedLabel();}}
function patch(id,changes){return change(s=>{const r=get(s,id);if(!r)throw Error(tr('Record no longer exists'));put(s,revise(r,changes,local.device.id));});}
const dateKey=(value,tz)=>new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const mapLink=s=>s.location?`https://www.google.com/maps/search/?api=1&query=${s.location.lat},${s.location.lng}`:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([s.name,s.city].filter(Boolean).join(', '))}`;
function gpsText(s){return s.location?`${s.location.lat.toFixed(5)}, ${s.location.lng.toFixed(5)}${s.location.accuracy!=null?' · ±'+Math.round(s.location.accuracy)+' m':''}${s.location.capturedAt?' · '+tr('fix')+' '+localTime(s.location.capturedAt,s.timezone):''}`:tr('Location not recorded');}

function connection(){ $('#connection').textContent=(navigator.onLine?tr('On device'):tr('Offline'))+' · '+(native?tr('Scout for Android'):tr('Scout in browser')); }
function render(){
  document.documentElement.lang=getLanguage()==='zh'?'zh-CN':'en';$('#language').value=getLanguage();$('#update-label').textContent=tr('Update Scout');$('#update button').textContent=tr('Update app · saves first, then reloads');$('.brand span').textContent=tr('FIELD NOTES');$('#nav').setAttribute('aria-label',tr('Main navigation')); document.title=tr('Scout · Field reference notebook');
  const oldForm=$('#set-form'),focused=document.activeElement;
  const expanded=oldForm?.dataset.set===selected?[...app.querySelectorAll('details[id][open]')].map(el=>el.id):[];
  const draft=formDirty&&view==='field'&&oldForm?.dataset.set===selected?{values:[...new FormData(oldForm)],focus:focused?.name,start:focused?.selectionStart,end:focused?.selectionEnd}:null;
  const links=[['field','⌖',tr('Field')],['library','▦',tr('Library')],['transfer','⇄',tr('Transfer')],['settings','⚙',tr('Trips & kit')]];
  $('#nav').innerHTML=links.map(([v,icon,title])=>html`<button data-action="nav" data-id="${v}" class="${view===v?'on':''}"><span>${icon}</span>${tr(title)}</button>`).join('');
  connection();
  if(!trip()&&view!=='settings'&&view!=='transfer'){app.innerHTML=welcome();return;}
  if(view==='field')app.innerHTML=selected&&get(state,selected)&&!get(state,selected).deleted?editor(get(state,selected)):field();
  if(view==='library')app.innerHTML=library();
  if(view==='transfer')app.innerHTML=transfer();
  if(view==='settings')app.innerHTML=settings();
  formDirty=!!draft;labelFields(app);for(const id of expanded){const el=document.getElementById(id);if(el)el.open=true;}
  if(draft&&$('#set-form')){const form=$('#set-form');for(const [name,value]of draft.values)if(form.elements[name])form.elements[name].value=value;const input=form.elements[draft.focus];if(input){input.focus({preventScroll:true});if(draft.start!=null&&input.setSelectionRange)input.setSelectionRange(draft.start,draft.end);}}
  savedLabel();
  $('#update').hidden=!updateReady;
}
function welcome(){return html`<div class="split"><section class="card hero"><div class="eyebrow" style="color:#d8e891">A field notebook for the way you see</div><h1>Bring the place<br>back with you.</h1><p class="muted">Sony originals. Phone observations. One connected reference library.</p>${button(tr('Capture here now'),'quick-start','','primary')} ${button(tr('Plan a trip'),'new-trip')}</section><section class="card"><h2>From street to studio</h2><p>01 &nbsp; Capture a place and photograph its code.</p><p>02 &nbsp; Save light readings, reference photos and observations.</p><p>03 &nbsp; Match camera originals on your computer and prepare a review package.</p><small>Works offline after the first load. Hong Kong is an optional starting itinerary.</small></section></div>`;}
function field(){const t=trip(),all=fieldsets(),open=all.filter(s=>!s.endedAt),readings=active(state,'reading').filter(r=>r.tripId===t.id);const last=all.find(s=>s.location);const light=last?daylight(dateKey(now(),last.timezone),last.location.lat,last.location.lng,last.timezone):null;
return html`<div class="heading row between"><div><div class="eyebrow">${e(t.city||tr('Anywhere'))} · ${e(t.timezone)}</div><h1>${e(t.name)}</h1></div>${button(tr('Switch trip'),'nav','settings')}</div>
<div class="split"><section class="card hero"><span class="tag live">FIELD CAPTURE</span><h2 style="font-size:29px;margin-top:18px">Found something worth keeping?</h2><p class="muted">Start a photo set anywhere. Photograph its code with your Sony, then get back to the scene.</p>${button(tr('+ Capture here'),'capture','','primary')}${open.length?html`<p>${open.length} open set${getLanguage()==='en'&&open.length>1?'s':''} · ${button(tr('Continue ')+e(open[0].code),'open',open[0].id)}</p>`:''}</section><section class="card"><div class="grid three"><div><div class="stat">${all.length}</div><small>Photo sets</small></div><div><div class="stat">${readings.length}</div><small>Light readings</small></div><div><div class="stat">${fieldAssets().length}</div><small>Images linked or waiting</small></div></div><hr class="divider">${light?html`<small>Solar estimate at your last recorded position</small><p>${tr(light.polar)||html`Sunrise ${localTime(light.rise,last.timezone)}<br>Sunset ${localTime(light.set,last.timezone)}`}</p><small>Buildings, hills and weather change the light on the street.</small>`:html('<p class="muted">A GPS fix or manual coordinates unlock local sunrise and sunset estimates.</p>')}</section></div>
<div class="row between"><h2>Your stops</h2><small>Each return visit is a new photo set</small></div>${all.length?all.map(s=>html`<section class="card"><div class="row between"><div><span class="tag ${s.endedAt?'':'live'}">${e(s.code)} · ${s.endedAt?tr('FINISHED'):tr('OPEN')}</span><h2 style="margin-top:12px">${e(s.name||tr('Untitled stop'))}</h2><small>${e(localTime(s.startedAt,s.timezone))} · ${e(s.city)}</small></div><div class="row">${button(tr('Open'),'open',s.id,'primary')}${button(tr('Revisit'),'revisit',s.id)}</div></div><p class="muted">${e(s.notes.slice(0,180)||tr('Add observations when you have a moment.'))}</p></section>`).join(''):html('<div class="empty">Your first capture starts here. No itinerary required.</div>')}
${t.template==='hongkong'?html`<details class="card"><summary>Hong Kong itinerary · optional suggestions</summary>${days.map(d=>html`<details><summary>${e(getLanguage()==='zh'?d.t:d.en)}</summary>${d.slots.map(([label,ids])=>html`<small>${e(getLanguage()==='zh'?label:({'白天':'Daytime','傍晚':'Dusk','夜晚':'Night','有空就补':'Flexible additions'}[label]||label))}</small>${ids.map(id=>{const p=places.find(p=>p.id===id);return html`<div class="list-item row between"><div><b>${e(getLanguage()==='zh'?p.n:p.en)}</b><p class="muted">${e(getLanguage()==='zh'?p.d:p.descriptionEn)}</p></div>${button(tr('Capture here'),'place',id)}</div>`;}).join('')}`).join('')}</details>`).join('')}<small>Suggestions are inherited from the original itinerary. Check current access and opening times yourself.</small></details>`:''}`;}

function editor(s){const readings=active(state,'reading').filter(r=>r.setId===s.id),assets=active(state,'asset').filter(a=>a.setId===s.id);const exposure=ev100(Number(s.camera.aperture),shutterSeconds(s.camera.shutter),Number(s.camera.iso));
return html`<div class="heading"><div class="row between">${button(tr('‹ All stops'),'back')}<span id="saved" class="status"></span></div><div class="row between"><div><div class="eyebrow">${e(s.code)} · ${s.endedAt?tr('Finished'):tr('Open photo set')}</div><h1>${e(s.name||tr('Untitled stop'))}</h1></div>${button(tr('Show camera slate'),'slate',s.id)}</div><small>${e(localTime(s.startedAt,s.timezone))}${s.endedAt?' → '+e(localTime(s.endedAt,s.timezone)):''} · ${e(s.timezone)}</small></div>
${nextStep(s,assets,readings)}<div class="split"><div><section class="card"><h2>The place</h2><p>${gpsPending.has(s.id)?tr('Finding your location…'):gpsErrors.get(s.id)?e(gpsErrors.get(s.id)):tr(s.location?'Location saved automatically; edit the name only if useful.':'You can keep shooting without a location.')}</p>${s.placeLookup?'<small>'+tr('Nearby area / street estimate; verify the exact subject.')+' · '+e(s.placeLookup.source)+'</small>':''}<form id="set-form" data-set="${e(s.id)}"><div class="form-grid"><div class="wide"><label for="set-name">Place name (optional)</label><input id="set-name" name="name" maxlength="300" value="${e(s.name)}"></div><details class="wide"><summary>Place details & capture options</summary><div class="form-grid"><div><label>City / destination</label><input name="city" value="${e(s.city)}" maxlength="200"></div><div><label>Capture mode</label><select name="mode"><option value="quick" ${s.mode==='quick'?'selected':''}>Quick reference</option><option value="survey" ${s.mode==='survey'?'selected':''}>Lighting survey</option></select></div></div></details><div class="wide"><label>Observations</label><textarea name="notes" maxlength="4000" placeholder="Light sources, weather, materials, useful angles…">${e(s.notes)}</textarea></div></div><div class="row">${button(tr('Get fresh GPS'),'gps',s.id)}${button(tr('Enter coordinates'),'coords',s.id)}<a class="button quiet" href="${e(mapLink(s))}" target="_blank" rel="noopener">Open map ↗</a></div><p class="muted" style="font-size:12px">${e(gpsText(s))}</p><details><summary>Camera snapshot and file boundaries</summary><div class="form-grid"><div><label>Camera (EXIF model name)</label><input name="cameraName" value="${e(s.camera.name)}" maxlength="200"></div><div><label>Fixed white balance, K</label><input name="wb" type="number" min="1000" max="50000" value="${e(s.camera.wb??'')}"></div><div><label>Aperture</label><input name="aperture" type="number" min="0.5" max="128" step="0.1" value="${e(s.camera.aperture??'')}"></div><div><label>ISO</label><input name="iso" type="number" min="1" value="${e(s.camera.iso||'')}"></div><div><label>Shutter, seconds or fraction</label><input name="shutter" value="${e(s.camera.shutter||'')}" placeholder="1/125"></div><div><label>First / last Sony filenames (optional)</label><input name="files" value="${e(s.files||'')}" placeholder="DSC01234 → DSC01258" maxlength="500"></div></div><small>Settings are saved with this set. Original EXIF remains authoritative for individual images. ${exposure!==null?tr('Exposure setting EV100: ')+fmt(exposure)+tr('. This is not measured scene lux.'):''}</small></details><p><button type="submit" class="primary">Save record</button></p><small>Edits save when you leave a field; wait for “Saved” before closing.</small></form></section>
<section class="card"><div class="row between"><h2>Reference images</h2><div class="row">${button(tr('Take photo'),'camera',s.id,'primary')}${button(tr('+ Add images'),'photo',s.id)}</div></div><p class="muted">Phone originals are kept unchanged alongside small previews. Sony originals stay on your computer.</p><div class="thumbs">${assets.map(a=>html`<figure>${a.blobId&&urls.get(a.blobId)?html`<img src="${urls.get(a.blobId)}" alt="${e(a.fileName)}">`:html('<div class="empty">No preview</div>')}<figcaption>${e(a.fileName)} · ${e(tr(a.role||'unclassified'))}</figcaption><div class="row">${button(tr('Color sample'),'color',a.id,'quiet')}${button(tr('Edit'),'asset',a.id,'quiet')}</div></figure>`).join('')}</div></section>
</div><div><details class="card" id="lighting-details" ${readings.length||s.mode==='survey'?'open':''}><summary>Lighting details & readings</summary><div class="row between"><h2>Lighting</h2><span class="tag">WITH PROVENANCE</span></div><p class="muted">Save readings at a named position. Keep the phone orientation consistent when comparing light.</p>${lightingActions(s.id)}${readings.length?readings.map(r=>html`<div class="list-item"><div class="row between"><b>${e(r.label||tr('Reading'))}</b><span>${fmt(r.value)} ${r.method.endsWith('lux')?'lux':'EV100'}</span></div><p>${e(r.instrument)} · ${e(tr(r.method))}</p><small>${e(r.protocol)} · ${e(tr(r.calibration))}</small>${r.samples?html`<p class="muted">Range ${fmt(r.samples.min)}–${fmt(r.samples.max)} · ${r.samples.count} samples</p>`:''}<div>${button(tr('Remove'),'delete',r.id,'quiet danger')}</div></div>`).join(''):html('<p class="muted">No measurements yet. Missing readings stay empty.</p>')}${comparison(readings)}</details>
<details class="card"><summary>Checklist & archive</summary><h2>Before you leave</h2><p>□ Code photographed on the Sony<br>□ Establishing view and useful details<br>□ ${s.mode==='survey'?html('Reference target and light readings<br>□ Brackets / lighting zones checked'):tr('One representative reference frame')}</p><div class="alert">Sony lens cover: uncalibrated target. Image samples describe rendered color, not measured Kelvin or physical albedo.</div>${s.endedAt?button(tr('Reopen this set'),'reopen',s.id):button(tr('Finish without more steps'),'finish',s.id)} ${button(tr('Archive set'),'delete',s.id,'quiet danger')}</details></div></div>`;}
function comparison(rs){const a=rs.at(-2),b=rs.at(-1);return a&&b&&comparable(a,b)?html`<div class="alert success">Last two comparable readings: ${fmt(b.value/a.value)}× · ${fmt(Math.log2(b.value/a.value))} stops (${e(b.label)} relative to ${e(a.label)}). Relative, uncalibrated comparison.</div>`:rs.length>1?html('<small>Ratios are shown only for positive readings from the same instrument, method, orientation protocol and calibration status.</small>'):'';}

function library(){const t=trip(),assets=fieldAssets().filter(a=>[a.fileName,a.role,tr(a.role),a.notes,...(a.tags||[])].join(' ').toLowerCase().includes(search.toLowerCase())),clocks=active(state,'clock').filter(c=>c.tripId===t.id);return html`<div class="heading"><div class="eyebrow">STUDIO REVIEW</div><h1>The reference library</h1><p class="muted">${e(t.name)} · Original files are never moved or rewritten.</p><div class="row">${button(tr('Import camera catalogue'),'import','','primary')}${button(tr('Camera clock segments'),'clocks')}${button(tr('Confirm unique suggestions'),'confirm-suggestions')}</div></div><label for="search">Search filenames, roles and notes</label><input id="search" value="${e(search)}" placeholder="Concrete, neon, DSC01234…"><p><small>Run the desktop importer to prepare camera metadata and previews. Imports never assign a photo set without your confirmation.</small></p><div class="grid three">${assets.map(a=>{const hint=!a.setId&&a.source==='camera'?suggest(a,sets(),clocks):null;const set=get(state,a.setId);return html`<section class="card asset">${a.blobId&&urls.has(a.blobId)?html`<img loading="lazy" src="${urls.get(a.blobId)}" alt="${e(a.fileName)}">`:html('<div class="empty">Preview unavailable</div>')}<h3 style="margin-top:12px">${e(a.fileName)}</h3><span class="tag ${set?'':'warn'}">${set?e(set.code):tr('UNRESOLVED')}</span> <span class="tag">${e(a.role||'unclassified')}</span><p class="muted">${e(a.notes||'')}</p><small>${e(a.originalRelativePath||tr('Phone reference'))}${a.captureWall?html('<br>Camera clock: ')+e(a.captureWall):''}</small>${hint?html`<p class="muted">${hint.sets.length===1?tr('Suggested: ')+e(hint.sets[0].code):hint.sets.length>1?tr('Ambiguous: overlapping sets'):e(hint.reason)+(hint.time?' · no closed set contains this time':'')}</p>`:''}<div class="row">${button(tr('Assign / describe'),'asset',a.id)}${a.blobId?button(tr('Color'),'color',a.id,'quiet'):''}</div></section>`;}).join('')}</div>${assets.length?'':html('<div class="empty">Import camera previews, or add reference images while capturing a set.</div>')}`;}
function transfer(){const t=trip(),conflicts=state.conflicts,deleted=state.records.filter(r=>r.deleted);return html`<div class="heading"><div class="eyebrow">DEVICE → STUDIO → DEVICE</div><h1>Bring everything together.</h1><p class="muted">Portable ZIP packages include records, previews and checksums. Imports merge changes.</p></div><div class="grid"><section class="card"><h2>Export ${e(t?.name||'a trip')}</h2><p>Keep an independent copy before clearing cards or browser data.</p><div class="row">${button(tr('Field backup'),'export','backup','primary')}${button(tr('Prepare AI handoff'),'export','handoff')}</div><p><small>${local.lastExport?tr('Last export handed to your device: ')+e(localTime(local.lastExport,'UTC'))+tr(' UTC. Destination and second-copy verification are still your responsibility.'):tr('No export recorded on this device.')}</small></p><p><small>Active trip only · Large trips split into parts · phone originals included; Sony originals external</small></p></section><section class="card"><h2>Import / verify a package</h2><p>Review additions and conflicts before applying. Reading a package also verifies its preview checksums.</p>${button(tr('Choose package'),'import','','primary')}<p><small>Scout ZIP, desktop catalogue ZIP, or original v1 JSON backup.</small></p></section></div><section class="card"><h2>Desktop RAW importer</h2><p>After copying the Sony card, run this from the repository on your computer:</p><pre>npm run catalogue -- --input "D:/Photos/Trip/Originals" --output "D:/Photos/Trip/Review"</pre><p class="muted">Creates resumable metadata, previews and import batches. Choose each catalogue ZIP above, add a clock segment, and review suggested matches.</p><small>The importer reads originals. It never renames, moves, deletes or writes metadata into them.</small></section>
<section class="card"><h2>Conflicts · ${conflicts.length}</h2>${conflicts.map(c=>{const current=get(state,c.incoming.id);return html`<div class="list-item"><b>${e(current.name||current.fileName||current.label||current.code||current.id)}</b><div class="grid"><div><p>This device ${current.deleted?'(deleted)':''}</p><pre>${e(JSON.stringify(current,null,2))}</pre>${button(tr('Keep this version'),'resolve-local',c.id)}</div><div><p>Incoming ${c.incoming.deleted?'(deleted)':''}</p><pre>${e(JSON.stringify(c.incoming,null,2))}</pre>${button(tr('Use incoming version'),'resolve-incoming',c.id)}</div></div></div>`;}).join('')||html('<p class="muted">No conflicting edits.</p>')}</section><details class="card"><summary>Recover archived records · ${deleted.length}</summary>${deleted.map(r=>html`<div class="list-item row between"><span>${e(r.kind)} · ${e(r.name||r.fileName||r.label||r.id)}</span>${button(tr('Restore'),'restore',r.id)}</div>`).join('')}</details>${state.legacy.length?html('<p class="muted">Original v1 metadata is retained in the export archive. Historical global settings are not asserted as capture facts.</p>'):''}`;}
function settings(){const all=active(state,'trip');return html`<div class="heading"><div class="eyebrow">MAKE IT YOUR FIELD NOTEBOOK</div><h1>Trips & equipment</h1></div><div class="grid"><section class="card"><div class="row between"><h2>Your trips</h2>${button(tr('+ New trip'),'new-trip','','primary')}</div>${all.map(t=>html`<div class="list-item row between"><div><b>${e(t.name)}</b><p class="muted">${e(t.city)} · ${e(t.timezone)}</p></div>${button(t.id===local.activeTrip?tr('Selected'):tr('Use trip'),'select-trip',t.id,t.id===local.activeTrip?'quiet':'')}</div>`).join('')||html('<p>No trips yet.</p>')}</section><section class="card"><h2>This device & camera defaults</h2><form id="kit-form"><label>Device label</label><input name="deviceName" value="${e(local.device.name)}" maxlength="160" required><label>Camera model (as shown in EXIF)</label><input name="camera" value="${e(local.camera||'ILCE-7CR')}" maxlength="200" required><div class="form-grid"><div><label>White balance default, K</label><input name="wb" type="number" min="1000" max="50000" value="${e(local.wb||'5500')}"></div><div><label>Aperture default</label><input name="aperture" type="number" min="0.5" max="128" step="0.1" value="${e(local.aperture||'')}"></div></div><p><button type="submit" class="primary">Save defaults</button></p><small>Only new sets use these defaults. Existing capture facts remain unchanged.</small></form></section></div><section class="card"><h2>Location names</h2><label class="inline-check"><input type="checkbox" id="place-names" ${local.onlinePlaceNames===true||local.onlinePlaceNames!==false&&nativePlaceNames?'checked':''}>Look up place names online</label><p>${nativePlaceNames?tr('Uses Android’s address provider for the current GPS fix.'):tr('Optional: sends this device’s current GPS coordinates to BigDataCloud for city / area names. It does not identify exact shops.')}</p><p>GPS coordinates save without an online lookup. You can continue offline or when permission is denied.</p></section><section class="card"><h2>App updates & camera recovery</h2>${button(tr('Check for updates'),'check-update','','primary')}${nativeCamera?button(tr('Recover camera captures'),'recover-captures'):''}<p>Updates preserve this installation’s records. Keep a field backup and approve the Android installer when prompted.</p></section><section class="card"><h2>Capture readiness</h2><p>□ Sony clock and phone time checked<br>□ Code photograph readable<br>□ RAW storage and battery ready<br>□ App opened once online, then tested offline<br>□ Previous shoot exported and verified</p><div class="alert">Live lux: Android sensor when available. iPhone and desktop browsers support manual readings. Camera EV is a separate estimate. No sensor is considered photographically calibrated.</div><p>Reference target: Sony lens cover (uncalibrated). A known neutral gray card improves exposure and color references.</p><small>Scout 2.1.0 · local files first · no analytics or automatic cloud/AI upload</small></section>`;}

async function newSet(name='',source=null){const t=trip();const time=now();const r=record('set',{tripId:t.id,createdDevice:local.device.id,code:'S-'+uid().replaceAll('-','').slice(0,10).toUpperCase(),name:name||tr('Untitled stop'),autoName:!name,city:source?.city||t.city,timezone:source?.timezone||t.timezone,startedAt:time,endedAt:null,mode:'quick',notes:'',tags:[],files:'',location:null,camera:{name:local.camera||'ILCE-7CR',wb:local.wb?Number(local.wb):5500,aperture:local.aperture?Number(local.aperture):null,iso:'',shutter:''}},local.device.id);await change(s=>{for(const old of active(s,'set').filter(x=>x.tripId===t.id&&!x.endedAt&&(x.createdDevice||x.device)===local.device.id))put(s,revise(old,{endedAt:time},local.device.id));put(s,r);});dirtyFields.clear();formDirty=false;selected=r.id;view='field';render();void autoLocate(r.id);await slate(r);}
async function slate(s){show(html`<div class="slate"><span class="eyebrow">PHOTOGRAPH THIS WITH YOUR SONY</span><div class="code">${e(s.code)}</div><p>${e(s.name)} · ${e(s.city)}</p><canvas id="qr"></canvas><time id="slate-time"></time><p>${e(s.timezone)}<br><small>The code identifies the set; the clock helps correct camera timestamps.</small></p>${button(tr('Code photographed → continue'),'slate-confirm',s.id,'primary')} ${button(tr('Phone only / skip code'),'slate-skip',s.id)}</div>`);await QRCode.toCanvas($('#qr'),JSON.stringify({app:'scout',v:2,tripId:s.tripId,setId:s.id,code:s.code}),{width:260,margin:2,errorCorrectionLevel:'M'});const tick=()=>{if($('#slate-time'))$('#slate-time').textContent=localTime(now(),s.timezone,true);};tick();const timer=setInterval(tick,1000);modal.addEventListener('close',()=>clearInterval(timer),{once:true});}
function tripDialog(){show(html`<h2>Start a trip</h2><form id="trip-form"><label>Trip name</label><input name="name" placeholder="Hong Kong · October references" maxlength="200"><label>Starting city / destination</label><input name="city" placeholder="Optional; location can fill this later" maxlength="200"><label>Time zone</label><input name="timezone" value="${e(Intl.DateTimeFormat().resolvedOptions().timeZone)}" placeholder="Asia/Hong_Kong" required><label>Starting itinerary</label><select name="template"><option value="blank">Blank · explore anywhere</option><option value="hongkong">Hong Kong reference locations</option></select><p><small>Use an IANA time zone such as Asia/Hong_Kong, Asia/Tokyo or America/Los_Angeles. Each set preserves its capture zone.</small></p><div class="row"><button type="submit" class="primary">Create trip</button>${button(tr('Cancel'),'close')}</div></form>`);}
function readingDialog(sid,measured=null){const s=get(state,sid);show(html`<h2>${measured?tr('Save phone measurement'):tr('Add lighting reading')}</h2><form id="reading-form" data-set="${e(sid)}"><label>Position / zone</label><input name="label" placeholder="Under awning, street center…" required maxlength="200"><div class="form-grid"><div><label>Method</label><select name="method" ${measured?'disabled':''}>${(measured?[['phone_lux',tr('Phone sensor · lux')]]:[['external_lux',tr('External / manual lux')],['camera_ev',tr('Camera meter · EV100')],['manual_ev',tr('External meter · EV100')]]).map(([k,v])=>html`<option value="${k}">${tr(v)}</option>`).join('')}</select></div><div><label>Value</label><input name="value" type="number" step="any" value="${measured?.value??''}" required ${measured?'readonly':''}></div></div><label>Instrument / source</label><input name="instrument" value="${e(measured?.instrument||'')}" placeholder="Meter model or measurement app" required maxlength="200"><label>Orientation / target protocol</label><input name="protocol" placeholder="Phone face upward, at 1.5 m / gray card spot reading…" required maxlength="500"><p><small>${measured?tr('Phone readings are uncalibrated. Stability is not accuracy.'):tr('Enter the meter’s ISO-100 EV reading, not exposure compensation. Keep lux and camera EV separate.')}</small></p><div class="row"><button type="submit" class="primary">Save reading</button>${button(tr('Cancel'),'close')}</div></form>`);sample=measured;}
function lightingActions(sid){
  const c=lightCapability;
  const android=c.mode==='browser'&&!c.available?html('<p><a class="button" href="')+androidDownload+html('">Download Scout for Android</a></p><small>Includes your notebook, photos and built-in meter in one app. Move existing browser records with Transfer → Field backup, then import the ZIP in Scout for Android.</small>'):'';
  return html('<div class="alert ')+(c.available?'success':'')+html('"><b>')+e(tr(c.title))+html('</b><p>')+e(tr(c.detail))+html('</p>')+android+html('</div><div class="row">')+(c.available?button(tr('Measure light'),'meter',sid,'primary'):'')+button(tr('Manual reading'),'reading',sid,c.available?'':'primary')+html('</div>');
}
async function meter(sid){
  sample=null;
  show(html('<h2>Scout built-in light meter</h2><p id="meter-status">Checking this device…</p>')+button(tr('Cancel'),'close'));
  const status=$('#meter-status');
  lightCapability=await getLightCapability();
  if(!modal.open||$('#meter-status')!==status)return;
  if(!lightCapability.available){show(html('<h2>Lighting on this device</h2>')+lightingActions(sid)+button(tr('Close'),'close'));return;}
  show(html`<h2>Scout built-in light meter</h2><p class="muted">Keep the sensor uncovered and the phone steady. A short sample starts when you tap below.</p><div class="metric" id="meter-value">—</div><p id="meter-status">${e(tr(lightCapability.title))} · uncalibrated</p><div class="row">${button(tr('Capture 4 seconds'),'meter-start',sid,'primary')}${button(tr('Manual reading'),'reading',sid)}${button(tr('Cancel'),'close')}</div>`);
}
function assetDialog(id){const a=get(state,id);show(html`<h2>Image association</h2><p>${e(a.fileName)}</p><details><summary>Original metadata & import notes</summary><p>${e(tr(a.previewSource||tr('Phone reference preview')))}</p><pre>${e(JSON.stringify(a.exif||{},null,2))}</pre><p>${e((a.warnings||[]).join(' · '))}</p></details>${(a.originals||[]).length?html('<h3>')+tr('Original files')+html('</h3>')+a.originals.map((o,i)=>button(tr('Save original')+' · '+e(o.fileName),'save-original',a.id+':'+i)).join(''):html('<p>')+tr('This older record has a preview only; its original was not stored in Scout.')+html('</p>')}${a.phoneCapture?html('<pre>')+e(JSON.stringify(a.phoneCapture,null,2))+html('</pre>'):''}<form id="asset-form" data-id="${e(id)}"><label>Photo set</label><select name="setId"><option value="">Unresolved</option>${sets().map(s=>html`<option value="${e(s.id)}" ${s.id===a.setId?'selected':''}>${e(s.code+' · '+s.name)}</option>`).join('')}</select><label>Reference role</label><select name="role">${roles.map(r=>html`<option value="${e(r)}" ${r===a.role?'selected':''}>${e(tr(r))}</option>`).join('')}</select><label>Tags (comma-separated)</label><input name="tags" value="${e((a.tags||[]).join(', '))}" maxlength="500"><label>Description / observations</label><textarea name="notes" maxlength="4000">${e(a.notes||'')}</textarea><small>${e(a.originalRelativePath||tr('Phone reference'))}<br>${e(a.sha256||'')}</small><p><button type="submit" class="primary">Save association</button> ${button(tr('Cancel'),'close')}</p></form>${button(tr('Archive image record'),'delete',id,'quiet danger')}`);}
function clocksDialog(){const clocks=active(state,'clock').filter(c=>c.tripId===local.activeTrip),cameras=[...new Set([local.camera||'ILCE-7CR',...fieldAssets().map(a=>a.camera).filter(Boolean)])];show(html`<h2>Camera clock correction</h2><p>Keep the original camera time. These segments only interpret it for matching. Photograph the phone clock to establish each correction.</p>${clocks.map(c=>html`<div class="list-item"><b>${e(c.camera)}</b><p>${e(c.from.slice(0,16))} → ${e(c.to.slice(0,16))}<br>UTC offset ${c.utcOffsetMinutes/60} h · correction ${c.offsetSeconds} s</p>${button(tr('Remove segment'),'delete',c.id,'quiet danger')}</div>`).join('')}<form id="clock-form"><label>Camera model</label><select name="camera">${cameras.map(c=>html`<option>${e(c)}</option>`).join('')}</select><label>Camera wall time · from</label><input type="datetime-local" name="from" required><label>Camera wall time · to</label><input type="datetime-local" name="to" required><div class="form-grid"><div><label>Camera UTC offset (hours)</label><input name="zone" type="number" min="-14" max="14" step="0.25" value="8" required></div><div><label>Add seconds to camera time</label><input name="offset" type="number" min="-172800" max="172800" step="0.1" value="0" required></div></div><p><small>If the camera is 90 seconds slow, enter +90. Use separate segments after clock or time-zone changes. Overlapping segments block suggestions.</small></p><button type="submit" class="primary">Add segment</button> ${button(tr('Close'),'close')}</form>`);}
function saveSetForm(form,redraw=false){
  const sid=selected,version=editVersion,f=new FormData(form),edited=new Set(dirtyFields);
  const fields={name:String(f.get('name')).trim(),city:String(f.get('city')).trim(),mode:f.get('mode'),notes:f.get('notes'),files:f.get('files'),camera:{name:String(f.get('cameraName')).trim()||tr('Unknown camera'),wb:f.get('wb')?Number(f.get('wb')):null,aperture:f.get('aperture')?Number(f.get('aperture')):null,iso:f.get('iso')||'',shutter:f.get('shutter')||''}};
  const save=async()=>{if(version<=(savedVersions.get(sid)??-1))return;const base=get(state,sid);if(!base)return;
    const cameraEdited=[...edited].some(k=>['cameraName','wb','aperture','iso','shutter'].includes(k));
    const changed=Object.fromEntries(Object.entries(fields).filter(([k,v])=>(edited.has(k)||(k==='camera'&&cameraEdited))&&JSON.stringify(v)!==JSON.stringify(base[k])));
    if(Object.hasOwn(changed,'name'))changed.autoName=false;
    if(!Object.keys(changed).length){savedVersions.set(sid,version);if(version===editVersion){formDirty=false;dirtyFields.clear();}savedLabel();return;}
    const incoming=revise(base,changed,local.device.id);let conflicts=0;
    await change(st=>{const result=merge(st,[incoming],uid());conflicts=result.conflicts;Object.assign(st,result.state);},redraw);
    savedVersions.set(sid,version);
    if(version===editVersion){formDirty=false;dirtyFields.clear();}savedLabel();
    if(conflicts)notice(tr('Another tab changed this record. Both versions are in Transfer → Conflicts.'),true);
  };
  formSave=formSave.catch(()=>{}).then(save);return formSave;
}

async function importFile(file){if(file.size>MAX_PACKAGE)throw Error(tr('Import limit is 64 MiB. Use smaller desktop batches.'));notice(tr('Reading package and checking attachments…'));
  if(file.name.toLowerCase().endsWith('.json')){const p=JSON.parse(await file.text());if(p.v===1){const records=migrateLegacy(p,'legacy-import');const blobs=[];for(const [id,o]of Object.entries(p.photoData||{})){if(typeof o.d!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(o.d))throw Error(tr('Unsupported legacy photo'));const bytes=Uint8Array.from(atob(o.d.split(',')[1]),c=>c.charCodeAt(0));const bid='legacy-'+id,blob=new Blob([bytes],{type:o.d.slice(5,o.d.indexOf(';'))});blobs.push({id:bid,blob,sha256:await sha256(bytes)});const parent=records.find(r=>r.kind==='set'&&r.legacyPoint?.id===o.pointId);if(parent){const r=record('asset',{tripId:'legacy-hk',setId:parent.id,fileName:'Legacy reference '+id,source:'field',blobId:bid,notes:'Original v1 compressed reference.',role:'unclassified'},'legacy-v1','legacy-image-'+id);r.revision=r.id+'-v1';r.updatedAt=parent.startedAt;records.push(r);}}const archive={...p};delete archive.photoData;pendingImport={packet:{packageId:'legacy-'+await sha256(new TextEncoder().encode(JSON.stringify(p))),records,legacy:[archive]},blobs};}
    else throw Error(tr('Use the desktop catalogue ZIP so previews and checksums travel with the metadata.'));
  }else{const files=unpack(new Uint8Array(await file.arrayBuffer()));if(files['field.json'])pendingImport=await decodeField(files);else if(files['catalogue.json']){await importCatalogue(files);return;}else throw Error(tr('Unrecognized ZIP package.'));}
  const preview=merge(state,pendingImport.packet.records,pendingImport.packet.packageId);show(html`<h2>Review import</h2><p>${preview.added} new records · ${preview.updated} newer versions · ${preview.conflicts} conflicts</p><p>${pendingImport.blobs.length} verified image attachments</p>${preview.duplicate?html('<div class="alert">This package has already been imported.</div>'):''}<p>Conflicting versions are retained for review. Older packages cannot silently undo newer records.</p><div class="row">${button(tr('Apply merge'),'apply-import','','primary')}${button(tr('Cancel'),'close')}</div>`);
}
async function importCatalogue(files){if(!trip())throw Error(tr('Select or create the destination trip first.'));const p=JSON.parse(strFromU8(files['catalogue.json']));if(p.format!=='scout-camera'||p.schemaVersion!==1||!Array.isArray(p.assets)||p.assets.length>1000)throw Error(tr('Unsupported camera catalogue.'));const records=[],blobs=[];let duplicates=0;
  for(const a of p.assets){if(!/^[a-f0-9]{64}$/.test(a.sha256)||typeof a.fileName!=='string'||typeof a.originalRelativePath!=='string')throw Error(tr('Invalid camera file manifest.'));const id='camera-'+trip().id+'-'+a.sha256;if(get(state,id)){duplicates++;continue;}let blobId=null;if(a.previewPath){const bytes=files[a.previewPath];if(!bytes||await sha256(bytes)!==a.previewSha256)throw Error(tr('Missing or corrupt camera preview: ')+a.fileName);blobId='preview-'+a.sha256;blobs.push({id:blobId,blob:new Blob([bytes],{type:'image/jpeg'}),sha256:a.previewSha256});}
    records.push(record('asset',{tripId:trip().id,setId:null,source:'camera',fileName:a.fileName,originalRelativePath:a.originalRelativePath,duplicatePaths:a.duplicatePaths||[],sha256:a.sha256,blobId,captureWall:a.captureWall||null,camera:a.camera||tr('Unknown camera'),previewSource:a.previewSource||tr('Imported preview'),exif:a.exif||{},warnings:a.warnings||[],role:'unclassified',notes:'',tags:[]},local.device.id,id));
  }
  validateRecords(records);pendingImport={catalogue:true,packet:{records,packageId:'camera-batch-'+await sha256(files['catalogue.json'])},blobs};show(html`<h2>Camera catalogue</h2><p>${records.length} new camera files · ${duplicates} already catalogued · ${blobs.length} previews</p><p>Files will enter the unresolved inbox for ${e(trip().name)}. Review the clock correction and suggested associations afterward.</p><div class="row">${button(tr('Import catalogue'),'apply-import','','primary')}${button(tr('Cancel'),'close')}</div>`);
}
async function applyImport(){const item=pendingImport;if(!item)return;const existing=new Map(snapshot.blobs.map(b=>[b.id,b]));for(const b of item.blobs){const old=existing.get(b.id);if(old&&await sha256(await old.blob.arrayBuffer())!==b.sha256)throw Error(tr('Attachment ID collision. No changes applied.'));}
 await change((s,b,l)=>{if(item.catalogue){for(const r of item.packet.records)if(!get(s,r.id))put(s,r);if(!s.packages.includes(item.packet.packageId))s.packages.push(item.packet.packageId);}else{const merged=merge(s,item.packet.records,item.packet.packageId);Object.assign(s,merged.state);for(const legacy of item.packet.legacy||[])if(!s.legacy.some(x=>JSON.stringify(x)===JSON.stringify(legacy)))s.legacy.push(legacy);}for(const blob of item.blobs)b.put(blob);if(!l.activeTrip)l.activeTrip=active(s,'trip')[0]?.id;});pendingImport=null;close();view=item.catalogue?'library':'transfer';selected=null;render();notice(tr('Import committed. Originals unchanged.'));}

async function savePhoneAsset(files,sid,capture=null){
 const assetId=capture?'phone-'+capture.id:uid();if(get(state,assetId))return;
 const prepared=await preparePhotos(files);const metadata=capture?Object.fromEntries(Object.entries(capture).filter(([key])=>!['files','setId'].includes(key))):null;
 await change((s,b)=>{const set=get(s,sid);if(!set||set.deleted)throw Error(tr('Photo set is archived'));if(get(s,assetId))return;for(const blob of prepared.blobs)b.put(blob);put(s,record('asset',{tripId:set.tripId,setId:sid,source:'field',fileName:files[0].name,blobId:prepared.blobId,originals:prepared.originals,phoneCapture:metadata,previewSource:tr('Rendered phone preview; originals preserved separately'),role:'unclassified',notes:'',tags:[],attachedAt:now()},local.device.id,assetId));},false);
}
async function addPhotos(files,sid){let success=0;const failures=[];for(const file of files){try{await savePhoneAsset([file],sid);success++;}catch(err){failures.push(file.name+': '+tr(err.message));}}
 render();notice(tr('Photos saved')+': '+success+(failures.length?' · '+tr('Failed')+': '+failures.length:''),!!failures.length);if(failures.length)show(html`<h2>Photo import results</h2><pre>${e(failures.join('\n'))}</pre>${button(tr('Close'),'close')}`);
}
function cameraDialog(sid){show(html`<h2>Capture a reference image</h2><p>RAW preserves sensor data. A JPEG or HEIC is already processed by the phone. Scout keeps the original file it receives without recompressing it.</p>${nativeCamera?html`<p>Scout’s camera checks RAW and manual Kelvin support on this phone. Available controls appear inside the camera.</p>${button(tr('Open Scout camera'),'native-camera',sid,'primary')}`:html`<div class="alert">This browser can open a camera, but cannot select Pro mode, RAW or manual Kelvin. The phone may show a camera chooser.</div>${button(tr('Open phone camera'),'browser-camera',sid,'primary')}`}<p>For the phone’s own Pro mode: open its camera, choose Pro / RAW and set white balance there, then return here and add the saved files. Scout cannot force that mode.</p>${button(tr('Choose existing images'),'photo',sid)} ${button(tr('Cancel'),'close')}`);}
async function acceptCapture(capture){
 const files=[];for(const item of capture.files)files.push(await readCaptureFile(item));
 await savePhoneAsset(files,capture.setId,capture);
 await acknowledgeCapture(capture.id);render();
 notice(tr('Originals and reference preview saved.'));if(capture.requestedKelvin&&(capture.actualKelvin!==capture.requestedKelvin||capture.actualAwbMode!==0||capture.actualColorMode!==3))notice(tr('Photo saved, but the camera did not confirm the requested Kelvin. Check image metadata.'),true);
}
async function updateDialog(){
 show(html('<h2>Scout updates</h2><p id="update-status">Checking GitHub releases…</p>')+button(tr('Close'),'close'));
 const status=$('#update-status');try{
 if(!native&&'serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration();if(reg){await reg.update();if(reg.installing)await new Promise(resolve=>{const worker=reg.installing,timer=setTimeout(resolve,8000);worker.addEventListener('statechange',()=>{if(['installed','redundant'].includes(worker.state)){clearTimeout(timer);resolve();}},{once:false});});updateReady=!!reg.waiting;$('#update').hidden=!updateReady;}}
 availableUpdate=await checkUpdate();if(!modal.open||$('#update-status')!==status)return;
 show(html`<h2>Scout updates</h2><p>${tr('Installed version')}: ${APP_VERSION}</p>${availableUpdate?html`<p>${tr('Available version')}: ${e(availableUpdate.version)} · ${fmt(availableUpdate.size/1024/1024)} MiB</p><p>Save a field backup first. Android checks the app signature and asks you to approve installation. Keep this app installed to preserve its data.</p>${native?button(tr('Download & install update'),'install-update','','primary'):html`<p>This is the browser edition. Use the web update banner to refresh it, or download Scout for Android from GitHub.</p>`}`:html('<p>No newer compatible Scout build was found.</p>')}<p><a href="${RELEASES_URL}" target="_blank" rel="noopener">Open GitHub releases ↗</a></p>${button(tr('Close'),'close')}`);
 if(!native&&updateReady)modal.insertAdjacentHTML('beforeend',button(tr('Apply browser update'),'update-app','','primary'));
 }catch(err){if(modal.open&&$('#update-status')===status){status.textContent=tr(err.message);if(!native&&updateReady)modal.insertAdjacentHTML('beforeend',button(tr('Apply browser update'),'update-app','','primary'));}}
}

async function colorDialog(id){const a=get(state,id),url=urls.get(a.blobId);if(!url)throw Error(tr('This asset has no preview'));show(html`<h2>Image color reference</h2><p>Click a matte, unclipped area. This samples the rendered preview, not RAW sensor values.</p><canvas id="color-canvas"></canvas><div id="color-result"></div><label>Target / interpretation</label><input id="color-target" value="Sony lens cover · uncalibrated" maxlength="200"><p><small>Keep lighting appearance and neutralized material references separate. This does not measure CCT or physical albedo.</small></p>${button(tr('Save sample in image notes'),'save-color',id,'primary')} ${button(tr('Close'),'close')}`);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});const canvas=$('#color-canvas');const scale=Math.min(1,900/img.width);canvas.width=img.width*scale;canvas.height=img.height*scale;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,canvas.width,canvas.height);sample=null;
 canvas.onclick=event=>{const rect=canvas.getBoundingClientRect(),x=Math.round((event.clientX-rect.left)*canvas.width/rect.width),y=Math.round((event.clientY-rect.top)*canvas.height/rect.height),left=Math.max(0,x-5),top=Math.max(0,y-5),w=Math.min(11,canvas.width-left),h=Math.min(11,canvas.height-top);const px=ctx.getImageData(left,top,w,h).data,linear=[0,0,0];let clipped=0;for(let i=0;i<px.length;i+=4){for(let j=0;j<3;j++){let v=px[i+j]/255;linear[j]+=v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}if(px[i]>245||px[i+1]>245||px[i+2]>245)clipped++;}linear.forEach((v,i)=>linear[i]=v/(px.length/4));const rgb=linear.map(v=>Math.round(255*(v<=.0031308?v*12.92:1.055*v**(1/2.4)-.055))),hex='#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join('');sample={rgb,hex,x:x/canvas.width,y:y/canvas.height,linear,clipped};$('#color-result').innerHTML=html`<p class="row"><span class="color-chip" style="background:${hex}"></span><b>${hex.toUpperCase()}</b> · sRGB ${rgb.join(', ')}</p>${clipped?html('<div class="alert">Some samples are near clipping. Choose another area.</div>'):''}`;};
}

