 if(action==='recover-captures'){el.disabled=true;const {captures}=await pendingCaptures();let count=0;for(const capture of captures){try{await acceptCapture(capture);count++;}catch(err){show(html('<h2>Camera recovery</h2><p>')+e(tr(err.message))+html('</p><p>Save these original files separately. Restore an archived stop before retrying its import.</p>')+button(tr('Save staged originals'),'share-capture',capture.id,'primary')+button(tr('Close'),'close'));return;}}notice(tr('Recovered captures')+': '+count);}
