async function legacyMigration(){if(local.legacyMigrated)return;let raw;try{raw=localStorage.getItem('hkscout_v1');}catch{}if(!raw){await change((s,b,l)=>l.legacyMigrated=true,false);return;}
 const old=JSON.parse(raw),records=migrateLegacy(old,'legacy-browser');let photos=[];
 photos=await new Promise((resolve,reject)=>{const q=indexedDB.open('hkscout');let created=false;q.onupgradeneeded=()=>created=true;q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result;if(created||!db.objectStoreNames.contains('photos')){db.close();resolve([]);return;}const tx=db.transaction('photos');const a=tx.objectStore('photos').getAll();tx.oncomplete=()=>{db.close();resolve(a.result||[]);};tx.onerror=()=>reject(tx.error);};});
 const blobs=[];for(const p of photos){const parent=records.find(r=>r.kind==='set'&&r.legacyPoint?.id===p.pointId);if(!parent)continue;const id='legacy-'+p.id;blobs.push({id,blob:p.blob,sha256:await sha256(await p.blob.arrayBuffer())});const r=record('asset',{tripId:'legacy-hk',setId:parent.id,source:'field',fileName:'Legacy reference '+p.id,blobId:id,role:'unclassified',notes:'Original v1 compressed reference.'},'legacy-v1','legacy-image-'+p.id);r.revision=r.id+'-v1';r.updatedAt=parent.startedAt;records.push(r);}
 await change((s,b,l)=>{for(const r of records)put(s,r);for(const blob of blobs)b.put(blob);s.legacy.push(old);l.legacyMigrated=true;l.activeTrip='legacy-hk';},false);notice(tr('Your original Hong Kong records were migrated. The v1 source was preserved.'));
}
async function boot(){try{await store.open();await refresh();await legacyMigration();lightCapability=await getLightCapability();render();if(sets().some(s=>!s.endedAt))notice(tr('An open photo set was recovered. Continue it or finish it before moving on.'));navigator.storage?.persist?.().catch(()=>{});if('serviceWorker'in navigator&&!native&&location.protocol!=='file:'){const reg=await navigator.serviceWorker.register('./sw.js');const offer=()=>{updateReady=!!reg.waiting;$('#update').hidden=!updateReady;if(updateReady)notice(tr('An app update is ready. Use Update app when your capture is saved.'));};reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',offer));offer();}}catch(err){app.innerHTML=html`<section class="card"><h1>Could not open the notebook</h1><p>${e(err.message)}</p><p>Your existing browser data has not been cleared. Export the v1 data from another existing tab if migration needs repair.</p></section>`;}}
boot();

function nextStep(s,assets,readings){
 if(s.endedAt)return html`<section class="card success" id="next-step"><h2>Stop complete</h2><p>Start the next stop, or export a backup when you finish shooting.</p>${button(tr('Start next stop'),'capture','','primary')}${button(tr('Back up this trip'),'export','backup')}</section>`;
 let title,detail,actions;
 if(!s.slateStatus){title=tr('1 · Photograph the Sony code');detail=tr('This connects your Sony originals to this stop. Skip it when using only your phone.');actions=button(tr('Show camera slate'),'slate',s.id,'primary')+button(tr('Phone only / skip code'),'slate-skip',s.id);}
 else if(!assets.length&&!s.referenceSkipped){title=tr('2 · Take a phone reference');detail=tr('Capture a useful view here. The original file stays intact.');actions=button(tr('Take reference photo'),'camera',s.id,'primary')+button(tr('Use an existing image'),'photo',s.id)+button(tr('Sony only / skip phone photo'),'skip-reference',s.id,'quiet');}
 else if(!readings.length&&!s.lightingSkipped){title=tr('3 · Record the light, if needed');detail=tr('Measure here or enter a meter reading. You can skip this for a quick visual reference.');actions=button(tr(lightCapability.available?'Measure light':'Add a light reading'),lightCapability.available?'meter':'reading',s.id,'primary')+button(tr('Skip lighting'),'skip-light',s.id);}
 else{title=tr('4 · Finish this stop');detail=tr('Take Sony RAW references and details, then finish to save the time boundary.');actions=button(tr('Finish stop'),'finish',s.id,'primary');}
 return html`<section class="card next-step" id="next-step"><div class="eyebrow">NEXT ACTION</div><h2>${title}</h2><p>${detail}</p><div class="row">${actions}${title!==tr('4 · Finish this stop')?button(tr('Finish stop now'),'finish',s.id,'quiet'):''}</div><small>${tr(gpsPending.has(s.id)?'GPS is being saved in the background.':'Your notes and reference images stay editable.')}</small>${!nativePlaceNames&&!local.onlinePlaceNames&&!s.placeLookup?'<p>'+button(tr('Enable online area names'),'enable-names',s.id,'quiet')+'</p><small>'+tr('Sends this device’s current GPS to BigDataCloud. Coordinates alone also work.')+'</small>':''}</section>`;
}
async function autoLocate(id){
 if(gpsPending.has(id))return;gpsPending.add(id);gpsErrors.delete(id);render();
 const previous=get(state,id)?.location?.capturedAt;
 try{
  const fix=await locate();
  let accepted=false;
  await change(s=>{const current=get(s,id);if(!current||current.deleted||current.location?.capturedAt!==previous)return;const updates={location:fix,placeLookup:null};if(current.autoName)updates.name=coordinateName(fix);put(s,revise(current,updates,local.device.id));accepted=true;});
  if(!accepted)return;
  const online=local.onlinePlaceNames===true||(nativePlaceNames&&local.onlinePlaceNames!==false);
  if(online&&navigator.onLine){
   try{
    const place=await Promise.race([nativePlaceNames?lookupNativePlace({...fix,language:getLanguage()}):lookupBrowserArea(fix,getLanguage()),new Promise(resolve=>setTimeout(()=>resolve(null),8000))]);
    if(place?.name)await change(s=>{const current=get(s,id);if(!current)return;const updates=automaticPlaceChanges(current,fix,place);if(Object.keys(updates).length)put(s,revise(current,updates,local.device.id));});
   }catch{/* Coordinates remain useful offline or when the provider is unavailable. */}
  }
 }catch{gpsErrors.set(id,tr('GPS unavailable. Keep shooting, retry GPS, or enter coordinates later.'));}
 finally{gpsPending.delete(id);render();}
}

let pendingStop=null;
async function beginSet(name='',source=null){const open=sets().find(s=>!s.endedAt&&(s.createdDevice||s.device)===local.device.id);if(!open){await newSet(name,source);return;}pendingStop={name,source};show(html`<h2>Finish the current stop first?</h2><p>${e(open.name)}</p><p>Starting the next stop saves the current stop’s end time.</p>${button(tr('Finish & start next stop'),'finish-start','','primary')} ${button(tr('Keep current stop'),'close')}`);}
